-- P1-02 P1 AW13-16 Circular + Trigonometry pack: CIR-03, TRI-02/03/04/05.
-- Original iClub-authored content. Governed publication only; public.questions remain draft + inactive.

begin;

insert into private.exam_prep_content_versions(program_version_id,content_version,component_code,release_label,status,source_policy)
select pv.id,'p1_aw13_16_circular_trig_v1','P1','P1 AW13-16 Circular measure + Trigonometry closure','draft',
       'Original iClub content only; Cambridge 9709 official syllabus defines scope; Complete Pure Mathematics 1 is mapping/teaching reference only; no Cambridge/coursebook question, diagram, answer or mark-scheme wording copied.'
from private.exam_prep_program_versions pv
where pv.program_key='math_as_p1_p5' and pv.version_key='p1_p5_canonical_v1_0'
on conflict(program_version_id,content_version) do nothing;

with cv as (
  select id from private.exam_prep_content_versions where content_version='p1_aw13_16_circular_trig_v1' and component_code='P1' and status='draft'
), src(skill,k,role,diff,qen,qru,quz,opts,ans,een,eru,euz,secs) as (values
('P1-CIR-03','P1CIR03-D01','diagnostic','medium','A sector has radius 6 and angle π/3 radians. What is its area?','Сектор имеет радиус 6 и угол π/3 радиан. Чему равна его площадь?','Sektor radiusi 6, burchagi π/3 radian. Uning yuzi nechaga teng?','["6π","12π","18π","36π"]','A','Sector area = 1/2 r²θ = 1/2×36×π/3 = 6π.','Площадь сектора = 1/2 r²θ = 1/2×36×π/3 = 6π.','Sektor yuzi = 1/2 r²θ = 1/2×36×π/3 = 6π.',70),
('P1-CIR-03','P1CIR03-L01','learning','easy','Find the area of a sector of radius 5 with angle 1.2 radians.','Найдите площадь сектора радиуса 5 с углом 1,2 радиан.','Radiusi 5 va burchagi 1.2 radian bo‘lgan sektor yuzini toping.','["15","30","6","25"]','A','1/2×5²×1.2 = 15.','1/2×5²×1,2 = 15.','1/2×5²×1.2 = 15.',50),
('P1-CIR-03','P1CIR03-L02','learning','medium','A sector has radius 4 and area 24. Find its angle in radians.','Сектор имеет радиус 4 и площадь 24. Найдите угол в радианах.','Sektor radiusi 4 va yuzi 24. Burchagini radianlarda toping.','["3","1.5","6","12"]','A','24 = 1/2×16×θ = 8θ, so θ=3.','24 = 1/2×16×θ = 8θ, поэтому θ=3.','24 = 1/2×16×θ = 8θ, demak θ=3.',65),
('P1-CIR-03','P1CIR03-L03','learning','medium','A sector of radius 4 has angle π/2. The triangle formed by the two radii has area 8. What is the area of the minor segment?','Сектор радиуса 4 имеет угол π/2. Площадь треугольника, образованного двумя радиусами, равна 8. Чему равна площадь малого сегмента?','Radiusi 4 bo‘lgan sektor burchagi π/2. Ikki radius hosil qilgan uchburchak yuzi 8. Kichik segment yuzi nechaga teng?','["4π−8","8π−8","4π+8","8"]','A','Sector area is 1/2×16×π/2=4π. Segment area = sector − triangle = 4π−8.','Площадь сектора 4π. Площадь сегмента = сектор − треугольник = 4π−8.','Sektor yuzi 4π. Segment yuzi = sektor − uchburchak = 4π−8.',75),
('P1-CIR-03','P1CIR03-R01','retest','easy','A sector has radius 3 and angle 2 radians. Find its area.','Сектор имеет радиус 3 и угол 2 радиана. Найдите площадь.','Sektor radiusi 3 va burchagi 2 radian. Yuzini toping.','["9","18","6","4.5"]','A','1/2×9×2 = 9.','1/2×9×2 = 9.','1/2×9×2 = 9.',45),
('P1-CIR-03','P1CIR03-R02','retest','medium','A sector has area 10 and angle 0.8 radians. Find its radius.','Площадь сектора равна 10, угол 0,8 радиан. Найдите радиус.','Sektor yuzi 10, burchagi 0.8 radian. Radiusini toping.','["5","4","2.5","25"]','A','10 = 1/2 r²(0.8)=0.4r², so r²=25 and r=5.','10 = 0,4r², поэтому r²=25 и r=5.','10 = 0.4r², demak r²=25 va r=5.',65),
('P1-CIR-03','P1CIR03-M01','mixed','medium','An annular sector has outer radius 6, inner radius 3 and angle π/3. Find its area.','Кольцевой сектор имеет внешний радиус 6, внутренний радиус 3 и угол π/3. Найдите его площадь.','Halqasimon sektor tashqi radiusi 6, ichki radiusi 3 va burchagi π/3. Yuzini toping.','["9π/2","3π","9π","27π/2"]','A','Area = 1/2(6²−3²)(π/3)=1/2×27×π/3=9π/2.','Площадь = 1/2(6²−3²)(π/3)=9π/2.','Yuza = 1/2(6²−3²)(π/3)=9π/2.',80),

('P1-TRI-02','P1TRI02-D01','diagnostic','medium','Find the exact value of sin 150°.','Найдите точное значение sin 150°.','sin 150° ning aniq qiymatini toping.','["1/2","−1/2","√3/2","−√3/2"]','A','150°=180°−30°. Sine is positive in quadrant II, so sin150°=sin30°=1/2.','150°=180°−30°. Во II четверти синус положителен, поэтому sin150°=1/2.','150°=180°−30°. II chorakda sinus musbat, shuning uchun sin150°=1/2.',60),
('P1-TRI-02','P1TRI02-L01','learning','easy','Find the exact value of cos 120°.','Найдите точное значение cos 120°.','cos 120° ning aniq qiymatini toping.','["−1/2","1/2","−√3/2","√3/2"]','A','120°=180°−60°. Cosine is negative in quadrant II, so cos120°=−cos60°=−1/2.','120°=180°−60°. Во II четверти косинус отрицателен: −1/2.','120°=180°−60°. II chorakda kosinus manfiy: −1/2.',50),
('P1-TRI-02','P1TRI02-L02','learning','medium','Find the exact value of tan 225°.','Найдите точное значение tan 225°.','tan 225° ning aniq qiymatini toping.','["1","−1","√3","0"]','A','225°=180°+45°. Tangent has period 180°, so tan225°=tan45°=1.','Тангенс имеет период 180°, поэтому tan225°=tan45°=1.','Tangens davri 180°, shuning uchun tan225°=tan45°=1.',55),
('P1-TRI-02','P1TRI02-L03','learning','medium','Find the exact value of sin 330°.','Найдите точное значение sin 330°.','sin 330° ning aniq qiymatini toping.','["−1/2","1/2","−√3/2","√3/2"]','A','330°=360°−30°. Sine is negative in quadrant IV, so sin330°=−1/2.','330°=360°−30°. В IV четверти синус отрицателен: −1/2.','330°=360°−30°. IV chorakda sinus manfiy: −1/2.',55),
('P1-TRI-02','P1TRI02-R01','retest','easy','Find the exact value of cos 300°.','Найдите точное значение cos 300°.','cos 300° ning aniq qiymatini toping.','["1/2","−1/2","√3/2","−√3/2"]','A','300°=360°−60° and cosine is positive in quadrant IV, so cos300°=1/2.','300°=360°−60°, косинус в IV четверти положителен: 1/2.','300°=360°−60°, IV chorakda kosinus musbat: 1/2.',45),
('P1-TRI-02','P1TRI02-R02','retest','medium','Find the exact value of tan 135°.','Найдите точное значение tan 135°.','tan 135° ning aniq qiymatini toping.','["−1","1","0","√3"]','A','135°=180°−45°. Tangent is negative in quadrant II, so tan135°=−1.','135°=180°−45°. Во II четверти тангенс отрицателен: −1.','135°=180°−45°. II chorakda tangens manfiy: −1.',50),
('P1-TRI-02','P1TRI02-M01','mixed','medium','Evaluate exactly: 2sin30° + cos180°.','Вычислите точно: 2sin30° + cos180°.','Aniq hisoblang: 2sin30° + cos180°.','["0","1","2","−2"]','A','2sin30° + cos180° = 2(1/2)−1 = 0.','2sin30° + cos180° = 1−1=0.','2sin30° + cos180° = 1−1=0.',55),

('P1-TRI-03','P1TRI03-D01','diagnostic','medium','Using principal values in degrees, evaluate cos⁻¹(−1/2).','Используя главное значение в градусах, вычислите cos⁻¹(−1/2).','Gradusdagi asosiy qiymatni ishlatib, cos⁻¹(−1/2) ni toping.','["120°","60°","240°","−60°"]','A','The principal arccos range is 0° to 180°. cos120°=−1/2, so the principal value is 120°.','Главный диапазон arccos — от 0° до 180°. cos120°=−1/2, поэтому ответ 120°.','arccos asosiy oralig‘i 0° dan 180° gacha. cos120°=−1/2, demak 120°.',65),
('P1-TRI-03','P1TRI03-L01','learning','easy','Evaluate sin⁻¹(1/2) as a principal value in degrees.','Вычислите главное значение sin⁻¹(1/2) в градусах.','sin⁻¹(1/2) ning gradusdagi asosiy qiymatini toping.','["30°","150°","330°","60°"]','A','The principal arcsin range is −90° to 90°, and sin30°=1/2.','Главный диапазон arcsin — от −90° до 90°, sin30°=1/2.','arcsin asosiy oralig‘i −90° dan 90° gacha, sin30°=1/2.',45),
('P1-TRI-03','P1TRI03-L02','learning','medium','Evaluate tan⁻¹(−1) as a principal value in degrees.','Вычислите главное значение tan⁻¹(−1) в градусах.','tan⁻¹(−1) ning gradusdagi asosiy qiymatini toping.','["−45°","45°","135°","225°"]','A','The principal arctan range is between −90° and 90°, so tan⁻¹(−1)=−45°.','Главное значение arctan лежит между −90° и 90°, поэтому −45°.','arctan asosiy qiymati −90° va 90° orasida, demak −45°.',50),
('P1-TRI-03','P1TRI03-L03','learning','medium','Evaluate sin⁻¹(−√3/2) as a principal value in degrees.','Вычислите главное значение sin⁻¹(−√3/2) в градусах.','sin⁻¹(−√3/2) ning gradusdagi asosiy qiymatini toping.','["−60°","60°","240°","300°"]','A','Within the principal arcsin range, sin(−60°)=−√3/2.','В главном диапазоне arcsin sin(−60°)=−√3/2.','arcsin asosiy oralig‘ida sin(−60°)=−√3/2.',55),
('P1-TRI-03','P1TRI03-R01','retest','easy','Evaluate cos⁻¹(0) as a principal value in degrees.','Вычислите главное значение cos⁻¹(0) в градусах.','cos⁻¹(0) ning gradusdagi asosiy qiymatini toping.','["90°","0°","180°","270°"]','A','cos90°=0 and 90° lies in the principal arccos range.','cos90°=0, и 90° лежит в главном диапазоне arccos.','cos90°=0 va 90° arccos asosiy oralig‘ida.',40),
('P1-TRI-03','P1TRI03-R02','retest','medium','Evaluate tan⁻¹(√3) as a principal value in degrees.','Вычислите главное значение tan⁻¹(√3) в градусах.','tan⁻¹(√3) ning gradusdagi asosiy qiymatini toping.','["60°","120°","240°","300°"]','A','tan60°=√3 and 60° is in the principal arctan range.','tan60°=√3, и 60° находится в главном диапазоне arctan.','tan60°=√3 va 60° arctan asosiy oralig‘ida.',50),
('P1-TRI-03','P1TRI03-M01','mixed','medium','A calculator gives cos⁻¹(0.25). Which value is the correct principal value to 1 decimal place?','Калькулятор вычисляет cos⁻¹(0,25). Каково правильное главное значение с точностью до 0,1°?','Kalkulyator cos⁻¹(0.25) ni hisoblaydi. 0.1° aniqlikdagi to‘g‘ri asosiy qiymat qaysi?','["75.5°","14.5°","284.5°","104.5°"]','A','cos⁻¹(0.25)≈75.522°, so to 1 decimal place it is 75.5°.','cos⁻¹(0,25)≈75,522°, поэтому 75,5°.','cos⁻¹(0.25)≈75.522°, demak 75.5°.',65),

('P1-TRI-04','P1TRI04-D01','diagnostic','medium','Simplify 1 − sin²x.','Упростите 1 − sin²x.','1 − sin²x ni soddalashtiring.','["cos²x","sin²x","tan²x","1"]','A','From sin²x+cos²x=1, we get 1−sin²x=cos²x.','Из sin²x+cos²x=1 получаем 1−sin²x=cos²x.','sin²x+cos²x=1 dan 1−sin²x=cos²x.',45),
('P1-TRI-04','P1TRI04-L01','learning','easy','Which identity is true for all x?','Какое тождество верно для всех x?','Qaysi ayniyat barcha x uchun to‘g‘ri?','["sin²x+cos²x=1","sin x+cos x=1","tan x=sin x cos x","sin²x−cos²x=1"]','A','The fundamental Pythagorean identity is sin²x+cos²x=1.','Основное пифагорово тождество: sin²x+cos²x=1.','Asosiy Pifagor ayniyati: sin²x+cos²x=1.',40),
('P1-TRI-04','P1TRI04-L02','learning','medium','For cos x ≠ 0, simplify sin x / cos x.','При cos x ≠ 0 упростите sin x / cos x.','cos x ≠ 0 bo‘lsa, sin x / cos x ni soddalashtiring.','["tan x","sin²x","cos²x","1"]','A','By definition, tan x = sin x / cos x.','По определению tan x = sin x / cos x.','Ta’rif bo‘yicha tan x = sin x / cos x.',40),
('P1-TRI-04','P1TRI04-L03','learning','medium','For sin x ≠ 0, simplify (1−cos²x)/sin x.','При sin x ≠ 0 упростите (1−cos²x)/sin x.','sin x ≠ 0 bo‘lsa, (1−cos²x)/sin x ni soddalashtiring.','["sin x","cos x","tan x","1"]','A','1−cos²x=sin²x, so sin²x/sin x=sin x.','1−cos²x=sin²x, поэтому sin²x/sin x=sin x.','1−cos²x=sin²x, demak sin²x/sin x=sin x.',55),
('P1-TRI-04','P1TRI04-R01','retest','easy','Complete the identity: sin²x = 1 − ___.','Дополните тождество: sin²x = 1 − ___.','Ayniyatni to‘ldiring: sin²x = 1 − ___.','["cos²x","cos x","tan²x","sin x"]','A','Rearrange sin²x+cos²x=1.','Переносим cos²x в тождестве sin²x+cos²x=1.','sin²x+cos²x=1 ni qayta yozamiz.',40),
('P1-TRI-04','P1TRI04-R02','retest','medium','For cos x ≠ 0, simplify (sin²x+cos²x)/cos x.','При cos x ≠ 0 упростите (sin²x+cos²x)/cos x.','cos x ≠ 0 bo‘lsa, (sin²x+cos²x)/cos x ni soddalashtiring.','["1/cos x","cos x","tan x","1"]','A','The numerator is 1, so the expression is 1/cos x.','Числитель равен 1, поэтому выражение равно 1/cos x.','Surat 1 ga teng, demak ifoda 1/cos x.',50),
('P1-TRI-04','P1TRI04-M01','mixed','medium','For sin x cos x ≠ 0, simplify (1−cos²x)/(sin x cos x).','При sin x cos x ≠ 0 упростите (1−cos²x)/(sin x cos x).','sin x cos x ≠ 0 bo‘lsa, (1−cos²x)/(sin x cos x) ni soddalashtiring.','["tan x","sin x","cos x","1"]','A','Replace 1−cos²x by sin²x, then cancel one sin x: sin x/cos x=tan x.','Заменяем 1−cos²x на sin²x и сокращаем: sin x/cos x=tan x.','1−cos²x ni sin²x ga almashtirib qisqartiramiz: sin x/cos x=tan x.',65),

('P1-TRI-05','P1TRI05-D01','diagnostic','medium','Solve sin θ = 1/2 for 0° ≤ θ ≤ 360°.','Решите sin θ = 1/2 при 0° ≤ θ ≤ 360°.','0° ≤ θ ≤ 360° uchun sin θ = 1/2 ni yeching.','["30°,150°","30°,330°","150°,210°","60°,120°"]','A','Reference angle is 30°. Sine is positive in quadrants I and II, giving 30° and 150°.','Опорный угол 30°. Синус положителен в I и II четвертях: 30° и 150°.','Tayanch burchak 30°. Sinus I va II choraklarda musbat: 30° va 150°.',75),
('P1-TRI-05','P1TRI05-L01','learning','easy','Solve cos θ = 1/2 for 0° ≤ θ < 360°.','Решите cos θ = 1/2 при 0° ≤ θ < 360°.','0° ≤ θ < 360° uchun cos θ = 1/2 ni yeching.','["60°,300°","60°,120°","120°,240°","30°,330°"]','A','Reference angle 60°; cosine is positive in quadrants I and IV: 60°,300°.','Опорный угол 60°; косинус положителен в I и IV четвертях: 60°,300°.','Tayanch burchak 60°; kosinus I va IV choraklarda musbat: 60°,300°.',55),
('P1-TRI-05','P1TRI05-L02','learning','medium','Solve tan θ = 1 for 0° ≤ θ < 360°.','Решите tan θ = 1 при 0° ≤ θ < 360°.','0° ≤ θ < 360° uchun tan θ = 1 ni yeching.','["45°,225°","45°,135°","135°,315°","90°,270°"]','A','Tangent has reference angle 45° and is positive in quadrants I and III: 45°,225°.','Опорный угол 45°; тангенс положителен в I и III четвертях: 45°,225°.','Tayanch burchak 45°; tangens I va III choraklarda musbat: 45°,225°.',55),
('P1-TRI-05','P1TRI05-L03','learning','medium','Solve sin θ = −√3/2 for 0° ≤ θ < 360°.','Решите sin θ = −√3/2 при 0° ≤ θ < 360°.','0° ≤ θ < 360° uchun sin θ = −√3/2 ni yeching.','["240°,300°","60°,120°","120°,240°","210°,330°"]','A','Reference angle is 60°. Sine is negative in quadrants III and IV: 240°,300°.','Опорный угол 60°. Синус отрицателен в III и IV четвертях: 240°,300°.','Tayanch burchak 60°. Sinus III va IV choraklarda manfiy: 240°,300°.',65),
('P1-TRI-05','P1TRI05-R01','retest','easy','Solve cos θ = −1/2 for 0° ≤ θ < 360°.','Решите cos θ = −1/2 при 0° ≤ θ < 360°.','0° ≤ θ < 360° uchun cos θ = −1/2 ni yeching.','["120°,240°","60°,300°","120°,300°","60°,240°"]','A','Reference angle 60°; cosine is negative in quadrants II and III: 120°,240°.','Опорный угол 60°; косинус отрицателен во II и III четвертях: 120°,240°.','Tayanch burchak 60°; kosinus II va III choraklarda manfiy: 120°,240°.',55),
('P1-TRI-05','P1TRI05-R02','retest','medium','Solve tan θ = −√3 for 0° ≤ θ < 360°.','Решите tan θ = −√3 при 0° ≤ θ < 360°.','0° ≤ θ < 360° uchun tan θ = −√3 ni yeching.','["120°,300°","60°,240°","120°,240°","60°,300°"]','A','Reference angle 60°; tangent is negative in quadrants II and IV: 120°,300°.','Опорный угол 60°; тангенс отрицателен во II и IV четвертях: 120°,300°.','Tayanch burchak 60°; tangens II va IV choraklarda manfiy: 120°,300°.',65),
('P1-TRI-05','P1TRI05-M01','mixed','medium','Solve 2sin θ = 1 for 0° ≤ θ ≤ 360°.','Решите 2sin θ = 1 при 0° ≤ θ ≤ 360°.','0° ≤ θ ≤ 360° uchun 2sin θ = 1 ni yeching.','["30°,150°","60°,120°","30°,330°","150°,330°"]','A','First sinθ=1/2. The solutions in the interval are 30° and 150°.','Сначала sinθ=1/2. Решения на интервале: 30° и 150°.','Avval sinθ=1/2. Oraliqdagi yechimlar: 30° va 150°.',60)
)
insert into public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
