('P1-TRI-05','P1TRI05-D01','diagnostic'),('P1-TRI-05','P1TRI05-L01','learning'),('P1-TRI-05','P1TRI05-L02','learning'),('P1-TRI-05','P1TRI05-L03','learning'),('P1-TRI-05','P1TRI05-R01','retest'),('P1-TRI-05','P1TRI05-R02','retest'),('P1-TRI-05','P1TRI05-M01','mixed')
