insert into private.exam_prep_question_content_meta(content_version_id,content_key,question_id,primary_skill_code,secondary_skill_codes,reserve_role,exposure_state,lifecycle_state,originality_attestation,provenance_note,official_scope_ref,coursebook_mapping_ref,copyright_status,qa_scope_status,qa_math_status,qa_language_status,qa_technical_status,diagnostic_rule_status,question_snapshot_md5)
select cv.id,k.k,q.id,k.skill,'{}'::text[],k.role,'withheld','draft','Original iClub-authored stem, values, distractors, answer and explanation; no protected question or mark-scheme wording copied.','Authored for p1_aw13_16_circular_trig_v1 from canonical skill intent using independent examples.','Cambridge 9709 2026-2027 v4; P1 Circular measure / Trigonometry','Complete Pure Mathematics 1; Circular measure / Trigonometry (mapping only)','pending','pending','pending','pending','pending',case when k.role='diagnostic' then 'pending' else 'not_applicable' end,
md5(concat_ws(chr(31),q.id::text,q.subject_id::text,coalesce(q.topic,''),coalesce(q.subtopic,''),coalesce(q.difficulty,''),coalesce(q.qtype,''),coalesce(q.question_text,''),coalesce(q.options_text,''),coalesce(q.correct_answer,''),coalesce(q.explanation,''),coalesce(q.image_url,''),coalesce(q.is_active::text,''),coalesce(q.question_text_ru,''),coalesce(q.question_text_uz,''),coalesce(q.question_text_en,''),coalesce(q.options_text_ru,''),coalesce(q.options_text_uz,''),coalesce(q.options_text_en,''),coalesce(q.explanation_ru,''),coalesce(q.explanation_uz,''),coalesce(q.explanation_en,''),coalesce(q.book_ref,''),coalesce(q.time_limit_sec::text,''),coalesce(q.quality_flag,''),coalesce(q.quality_status,'')))
from cv cross join keys k join public.questions q on q.book_ref='ExamPrep:P1:p1_aw13_16_circular_trig_v1:'||k.k
on conflict(content_version_id,content_key) do nothing;

with rules(ckey,match,dcode,mtype,skill,fen,fru,fuz,nen,nru,nuz) as (values
('P1CIR03-D01','B','missed_half_factor','method','P1-CIR-03','Sector area includes the factor 1/2. Using r²θ gives twice the correct area.','В формуле площади сектора есть множитель 1/2. r²θ даёт вдвое больший ответ.','Sektor yuzi formulasida 1/2 bor. r²θ javobni ikki baravar qiladi.','Use A=1/2 r²θ with θ in radians.','Используйте A=1/2 r²θ при θ в радианах.','θ radian bo‘lsa A=1/2 r²θ ni ishlating.'),
('P1CIR03-D01','C','angle_handling_error','method','P1-CIR-03','π/3 must multiply 18; it is not replaced by π.','π/3 нужно умножить на 18; нельзя заменять его на π.','π/3 ni 18 ga ko‘paytirish kerak; uni π bilan almashtirmang.','Substitute r and θ before simplifying.','Сначала подставьте r и θ, затем упрощайте.','Avval r va θ ni qo‘ying, keyin soddalashtiring.'),
('P1CIR03-D01','D','used_full_circle_area','concept','P1-CIR-03','36π is the area of the full circle, not the π/3 sector.','36π — площадь всего круга, а не сектора π/3.','36π butun doira yuzi, π/3 sektor yuzi emas.','Compare θ with 2π to see what fraction of the full circle is used.','Сравните θ с 2π, чтобы увидеть долю полного круга.','θ ni 2π bilan solishtirib doiraning qaysi qismi olinganini ko‘ring.'),
('P1TRI02-D01','B','quadrant_sign_error','concept','P1-TRI-02','150° is in quadrant II, where sine is positive.','150° находится во II четверти, где синус положителен.','150° II chorakda, bu yerda sinus musbat.','Find the reference angle and then apply the quadrant sign.','Найдите опорный угол и затем знак по четверти.','Tayanch burchakni topib, chorak ishorasini qo‘llang.'),
('P1TRI02-D01','C','wrong_exact_function_value','concept','P1-TRI-02','√3/2 is cos30° (and sin60°), not sin30°.','√3/2 — это cos30° (и sin60°), а не sin30°.','√3/2 cos30° (va sin60°), sin30° emas.','Recall the 30°/60° exact-value triangle.','Вспомните точные значения для 30°/60°.','30°/60° aniq qiymatlarini eslang.'),
('P1TRI02-D01','D','value_and_sign_error','method','P1-TRI-02','Both the reference value and quadrant sign are wrong.','Неверны и опорное значение, и знак четверти.','Tayanch qiymat ham, chorak ishorasi ham noto‘g‘ri.','Separate magnitude from sign: sin30° first, then quadrant II sign.','Разделите модуль и знак: сначала sin30°, затем знак II четверти.','Qiymat va ishorani ajrating: avval sin30°, keyin II chorak ishorasi.'),
('P1TRI03-D01','B','ignored_negative_cosine','concept','P1-TRI-03','cos60° is +1/2, not −1/2. The negative value has principal angle 120°.','cos60°=+1/2, а не −1/2. Отрицательному значению соответствует 120°.','cos60°=+1/2. Manfiy qiymatning asosiy burchagi 120°.','Check the sign of cosine at the candidate angle.','Проверьте знак косинуса у выбранного угла.','Tanlangan burchakda kosinus ishorasini tekshiring.'),
('P1TRI03-D01','C','used_nonprincipal_solution','concept','P1-TRI-03','240° also has cosine −1/2, but it is outside the principal arccos range 0°–180°.','cos240° тоже равен −1/2, но 240° вне главного диапазона arccos 0°–180°.','cos240° ham −1/2, lekin 240° arccos asosiy 0°–180° oralig‘idan tashqarida.','For inverse functions, enforce the principal-value range.','Для обратных функций соблюдайте диапазон главных значений.','Teskari funksiyada asosiy qiymat oralig‘ini tekshiring.'),
('P1TRI03-D01','D','wrong_inverse_range','concept','P1-TRI-03','−60° is not in the principal arccos range and cos(−60°)=+1/2.','−60° не входит в главный диапазон arccos, и cos(−60°)=+1/2.','−60° arccos asosiy oralig‘ida emas va cos(−60°)=+1/2.','Use arccos range [0°,180°] and verify by substitution.','Используйте диапазон arccos [0°,180°] и проверьте подстановкой.','arccos [0°,180°] oralig‘ini ishlating va tekshirib ko‘ring.'),
('P1TRI04-D01','B','identity_rearrangement_error','concept','P1-TRI-04','The Pythagorean identity gives cos²x after subtracting sin²x from 1.','Пифагорово тождество даёт cos²x после вычитания sin²x из 1.','Pifagor ayniyatida 1 dan sin²x ayirilsa cos²x qoladi.','Start from sin²x+cos²x=1 and rearrange one term at a time.','Начните с sin²x+cos²x=1 и перенесите один член.','sin²x+cos²x=1 dan boshlab bir hadni ko‘chiring.'),
('P1TRI04-D01','C','confused_tangent_identity','concept','P1-TRI-04','tan x is a ratio sin x/cos x; it is not equal to 1−sin²x.','tan x — отношение sin x/cos x; оно не равно 1−sin²x.','tan x = sin x/cos x; u 1−sin²x ga teng emas.','Keep the ratio identity separate from the Pythagorean identity.','Не смешивайте отношение для tan с пифагоровым тождеством.','tan nisbat ayniyatini Pifagor ayniyatidan ajrating.'),
('P1TRI04-D01','D','dropped_variable_term','method','P1-TRI-04','1−sin²x varies with x; it is not identically 1.','1−sin²x зависит от x и не равно тождественно 1.','1−sin²x x ga bog‘liq, doim 1 emas.','Use the identity before simplifying.','Перед упрощением примените тождество.','Soddalashtirishdan oldin ayniyatni qo‘llang.'),
('P1TRI05-D01','B','wrong_second_quadrant','concept','P1-TRI-05','330° has negative sine. For positive sine, the second solution is in quadrant II at 150°.','У 330° синус отрицателен. Для положительного синуса второе решение во II четверти: 150°.','330° da sinus manfiy. Musbat sinus uchun ikkinchi yechim II chorakda: 150°.','Use the reference angle 30° and the sign of sine by quadrant.','Используйте опорный угол 30° и знак синуса по четвертям.','30° tayanch burchak va sinus ishoralarini ishlating.'),
('P1TRI05-D01','C','wrong_reference_pair','method','P1-TRI-05','150° is valid, but 210° has sine −1/2, so the pair is incomplete/wrong.','150° подходит, но sin210°=−1/2, поэтому пара неверна.','150° to‘g‘ri, lekin sin210°=−1/2, shuning uchun juft noto‘g‘ri.','Check every candidate by substitution.','Проверьте каждый кандидат подстановкой.','Har bir variantni qo‘yib tekshiring.'),
('P1TRI05-D01','D','used_cosine_reference','concept','P1-TRI-05','60° and 120° have sine √3/2, not 1/2.','sin60° и sin120° равен √3/2, а не 1/2.','sin60° va sin120° = √3/2, 1/2 emas.','The reference angle for sinθ=1/2 is 30°, not 60°.','Опорный угол для sinθ=1/2 равен 30°, а не 60°.','sinθ=1/2 uchun tayanch burchak 30°, 60° emas.')
), meta as (
select m.id,m.content_key from private.exam_prep_question_content_meta m join private.exam_prep_content_versions cv on cv.id=m.content_version_id where cv.content_version='p1_aw13_16_circular_trig_v1' and m.reserve_role='diagnostic')
insert into private.exam_prep_diagnostic_rules(content_meta_id,rule_version,answer_kind,answer_match,distractor_code,mistake_type,weak_skill_code,feedback_en,feedback_ru,feedback_uz,next_action_en,next_action_ru,next_action_uz,status,approved_at)
select meta.id,'drv1','mcq_option',r.match,r.dcode,r.mtype,r.skill,r.fen,r.fru,r.fuz,r.nen,r.nru,r.nuz,'approved',now() from rules r join meta on meta.content_key=r.ckey
on conflict(content_meta_id,rule_version,answer_kind,answer_match) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p1_aw13_16_circular_trig_v1' and status='draft'), defs(task_key,skill,en,ru,uz,rubric,sen,sru,suz) as (values
('P1CIR03-W01','P1-CIR-03','A sector has radius 8 and angle 1.1 radians. (a) Find its area. (b) The triangle formed by the radii has area 25.6. Find the area of the corresponding segment. (c) A concentric inner sector of radius 5 with the same angle is removed. Find the remaining annular-sector area. Show the formula used in each part.','Сектор имеет радиус 8 и угол 1,1 радиан. (a) Найдите его площадь. (b) Площадь треугольника между радиусами равна 25,6. Найдите площадь соответствующего сегмента. (c) Удаляют концентрический сектор радиуса 5 с тем же углом. Найдите оставшуюся площадь кольцевого сектора. Покажите формулу в каждой части.','Sektor radiusi 8 va burchagi 1.1 radian. (a) Yuzini toping. (b) Radiuslar orasidagi uchburchak yuzi 25.6. Segment yuzini toping. (c) Shu burchakli radiusi 5 ichki sektor olib tashlanadi. Qolgan halqasimon sektor yuzini toping. Har qismda formulani ko‘rsating.','{"max_marks":10,"criteria":[{"id":"sector","marks":3,"rule":"Uses 1/2×8²×1.1=35.2."},{"id":"segment","marks":2,"rule":"Finds 35.2−25.6=9.6."},{"id":"annular","marks":3,"rule":"Uses 1/2(8²−5²)1.1=21.45."},{"id":"method","marks":2,"rule":"Uses radians consistently and distinguishes sector, segment and annular-sector subtraction."}]}','Check the 1/2 factor and keep the same angle in both concentric sectors. A segment is sector minus triangle.','Проверьте множитель 1/2 и используйте один и тот же угол для концентрических секторов. Сегмент = сектор − треугольник.','1/2 ko‘paytuvchini tekshiring va ikkala konsentrik sektorda bir xil burchakni ishlating. Segment = sektor − uchburchak.'),
('P1TRI02-W01','P1-TRI-02','Without a calculator, find the exact values of sin150°, cos240°, tan315° and 2sin30°−cos180°. For each single angle, state the reference angle and the quadrant sign.','Без калькулятора найдите точные значения sin150°, cos240°, tan315° и 2sin30°−cos180°. Для каждого отдельного угла укажите опорный угол и знак по четверти.','Kalkulyatorsiz sin150°, cos240°, tan315° va 2sin30°−cos180° ning aniq qiymatlarini toping. Har bir alohida burchak uchun tayanch burchak va chorak ishorasini yozing.','{"max_marks":10,"criteria":[{"id":"sin","marks":2,"rule":"sin150°=1/2 with reference 30° and positive QII sign."},{"id":"cos","marks":2,"rule":"cos240°=−1/2 with reference 60° and negative QIII sign."},{"id":"tan","marks":2,"rule":"tan315°=−1 with reference 45° and negative QIV sign."},{"id":"expression","marks":2,"rule":"2(1/2)−(−1)=2."},{"id":"communication","marks":2,"rule":"Separates exact magnitude from quadrant sign consistently."}]}','Use a reference angle first, then apply the sign. Do not convert exact values to decimals.','Сначала находите опорный угол, затем применяйте знак. Не переводите точные значения в десятичные.','Avval tayanch burchakni toping, keyin ishorani qo‘llang. Aniq qiymatlarni o‘nli songa aylantirmang.'),
('P1TRI03-W01','P1-TRI-03','State the principal-value ranges in degrees for sin⁻¹, cos⁻¹ and tan⁻¹. Then evaluate sin⁻¹(−1/2), cos⁻¹(−√3/2) and tan⁻¹(1). Finally explain why a principal inverse value is not automatically the full solution set of a trigonometric equation.','sin⁻¹, cos⁻¹ и tan⁻¹ үшін градусах укажите диапазоны главных значений. Затем вычислите sin⁻¹(−1/2), cos⁻¹(−√3/2) и tan⁻¹(1). В конце объясните, почему главное значение обратной функции не является автоматически полным набором решений тригонометрического уравнения.','sin⁻¹, cos⁻¹ va tan⁻¹ uchun gradusdagi asosiy qiymat oraliqlarini yozing. So‘ng sin⁻¹(−1/2), cos⁻¹(−√3/2) va tan⁻¹(1) ni toping. Oxirida asosiy teskari qiymat trigonometrik tenglamaning barcha yechimlari emasligini tushuntiring.','{"max_marks":10,"criteria":[{"id":"ranges","marks":3,"rule":"States arcsin [−90°,90°], arccos [0°,180°], arctan (−90°,90°)."},{"id":"values","marks":3,"rule":"Obtains −30°,150°,45° respectively."},{"id":"meaning","marks":2,"rule":"Explains inverse functions return one principal value."},{"id":"equation_link","marks":2,"rule":"Explains full equations require symmetry/periodicity and interval filtering."}]}','Keep inverse-function range and equation-solution interval as two different ideas.','Разделяйте диапазон главного значения обратной функции и интервал решений уравнения.','Teskari funksiyaning asosiy oralig‘i bilan tenglama yechim oralig‘ini ajrating.'),
('P1TRI04-W01','P1-TRI-04','Prove, for values where the expressions are defined, that (1−cos²x)/(sin x cos x)=tan x. Then simplify (sin²x+cos²x)/(1−sin²x) and state any denominator restriction you use.','Докажите для допустимых x, что (1−cos²x)/(sin x cos x)=tan x. Затем упростите (sin²x+cos²x)/(1−sin²x) и укажите ограничения на знаменатели.','Ifodalar aniqlangan x lar uchun (1−cos²x)/(sin x cos x)=tan x ekanini isbotlang. So‘ng (sin²x+cos²x)/(1−sin²x) ni soddalashtiring va maxraj cheklovlarini yozing.','{"max_marks":10,"criteria":[{"id":"first_identity","marks":4,"rule":"Uses 1−cos²x=sin²x, cancels valid sin x, obtains sin x/cos x=tan x."},{"id":"second_identity","marks":3,"rule":"Uses numerator=1 and denominator=cos²x, obtaining 1/cos²x."},{"id":"restrictions","marks":2,"rule":"Notes the original denominators require sin x cos x≠0 for the first and cos x≠0 for the second."},{"id":"logic","marks":1,"rule":"Transforms one side rather than assuming the result."}]}','Use only established identities and keep track of what you cancel.','Используйте только известные тождества и следите за тем, что сокращаете.','Faqat ma’lum ayniyatlardan foydalaning va nimani qisqartirayotganingizni kuzating.'),
('P1TRI05-W01','P1-TRI-05','Solve on 0°≤θ<360°: (a) sinθ=√3/2, (b) cosθ=−1/2, (c) tanθ=−1. For each equation, show the reference angle, identify the valid quadrants and list every solution in the interval.','Решите при 0°≤θ<360°: (a) sinθ=√3/2, (b) cosθ=−1/2, (c) tanθ=−1. Для каждого уравнения покажите опорный угол, нужные четверти и все решения на интервале.','0°≤θ<360° da yeching: (a) sinθ=√3/2, (b) cosθ=−1/2, (c) tanθ=−1. Har bir tenglama uchun tayanch burchak, mos choraklar va oraliqdagi barcha yechimlarni yozing.','{"max_marks":10,"criteria":[{"id":"sin","marks":3,"rule":"Uses reference 60°, QI/QII, solutions 60°,120°."},{"id":"cos","marks":3,"rule":"Uses reference 60°, QII/QIII, solutions 120°,240°."},{"id":"tan","marks":3,"rule":"Uses reference 45°, QII/QIV, solutions 135°,315°."},{"id":"interval","marks":1,"rule":"No duplicated or out-of-interval solutions."}]}','For each equation: principal/reference angle → sign quadrants → interval check.','Для каждого уравнения: опорный угол → четверти по знаку → проверка интервала.','Har bir tenglama: tayanch burchak → ishora choraklari → oraliq tekshiruvi.')
)
