('p1_tri03_learning',1,'P1TRI03-L01',null,'P1-TRI-03','learning',false),('p1_tri03_learning',2,'P1TRI03-L02',null,'P1-TRI-03','learning',false),('p1_tri03_learning',3,'P1TRI03-L03',null,'P1-TRI-03','learning',false),('p1_tri03_learning',4,null,'P1TRI03-W01','P1-TRI-03','written',false),
('p1_tri04_learning',1,'P1TRI04-L01',null,'P1-TRI-04','learning',false),('p1_tri04_learning',2,'P1TRI04-L02',null,'P1-TRI-04','learning',false),('p1_tri04_learning',3,'P1TRI04-L03',null,'P1-TRI-04','learning',false),('p1_tri04_learning',4,null,'P1TRI04-W01','P1-TRI-04','written',false),
('p1_tri05_learning',1,'P1TRI05-L01',null,'P1-TRI-05','learning',false),('p1_tri05_learning',2,'P1TRI05-L02',null,'P1-TRI-05','learning',false),('p1_tri05_learning',3,'P1TRI05-L03',null,'P1-TRI-05','learning',false),('p1_tri05_learning',4,null,'P1TRI05-W01','P1-TRI-05','written',false),
('p1_cir03_retest',1,'P1CIR03-R01',null,'P1-CIR-03','retest',true),('p1_tri02_retest',1,'P1TRI02-R01',null,'P1-TRI-02','retest',true),('p1_tri03_retest',1,'P1TRI03-R01',null,'P1-TRI-03','retest',true),('p1_tri04_retest',1,'P1TRI04-R01',null,'P1-TRI-04','retest',true),('p1_tri05_retest',1,'P1TRI05-R01',null,'P1-TRI-05','retest',true),
('p1_aw13_16_circular_trig_mixed',1,'P1CIR03-M01',null,'P1-CIR-03','mixed',true),('p1_aw13_16_circular_trig_mixed',2,'P1TRI02-M01',null,'P1-TRI-02','mixed',true),('p1_aw13_16_circular_trig_mixed',3,'P1TRI03-M01',null,'P1-TRI-03','mixed',true),('p1_aw13_16_circular_trig_mixed',4,'P1TRI04-M01',null,'P1-TRI-04','mixed',true),('p1_aw13_16_circular_trig_mixed',5,'P1TRI05-M01',null,'P1-TRI-05','mixed',true)
)
insert into private.exam_prep_assessment_items(assessment_id,item_order,question_id,written_task_id,primary_skill_code,reserve_role,is_holdout)
select a.id,i.ord,m.question_id,w.id,i.skill,i.role,i.holdout from items i join a on a.assessment_key=i.akey left join m on m.content_key=i.ckey left join w on w.task_key=i.wkey
on conflict(assessment_id,item_order) do nothing;

-- Static QA.
do $$ declare v_id bigint; v_skill text; v_bad int; begin
select id into v_id from private.exam_prep_content_versions where content_version='p1_aw13_16_circular_trig_v1' and status='draft';
if v_id is null then raise exception 'P1 AW13 circular/trig draft missing'; end if;
if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id)<>35 then raise exception 'P1 AW13 circular/trig expected 35 questions'; end if;
foreach v_skill in array array['P1-CIR-03','P1-TRI-02','P1-TRI-03','P1-TRI-04','P1-TRI-05'] loop
 if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id and primary_skill_code=v_skill and reserve_role='diagnostic')<>1 then raise exception '% diagnostic floor',v_skill; end if;
 if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id and primary_skill_code=v_skill and reserve_role='learning')<>3 then raise exception '% learning floor',v_skill; end if;
 if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id and primary_skill_code=v_skill and reserve_role='retest')<>2 then raise exception '% retest floor',v_skill; end if;
 if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id and primary_skill_code=v_skill and reserve_role='mixed')<>1 then raise exception '% mixed floor',v_skill; end if;
 if (select count(*) from private.exam_prep_written_tasks where content_version_id=v_id and primary_skill_code=v_skill and lifecycle_state='approved')<>1 then raise exception '% written floor',v_skill; end if;
end loop;
select count(*) into v_bad from private.exam_prep_question_content_meta m join public.questions q on q.id=m.question_id where m.content_version_id=v_id and (q.subject_id<>5 or q.is_active or q.quality_status is distinct from 'draft' or nullif(trim(q.question_text_en),'') is null or nullif(trim(q.question_text_ru),'') is null or nullif(trim(q.question_text_uz),'') is null or nullif(trim(q.options_text_en),'') is null or jsonb_typeof(q.options_text_en::jsonb)<>'array' or jsonb_array_length(q.options_text_en::jsonb)<>4 or q.correct_answer not in ('A','B','C','D') or nullif(trim(q.explanation_en),'') is null or nullif(trim(q.explanation_ru),'') is null or nullif(trim(q.explanation_uz),'') is null or md5(concat_ws(chr(31),q.id::text,q.subject_id::text,coalesce(q.topic,''),coalesce(q.subtopic,''),coalesce(q.difficulty,''),coalesce(q.qtype,''),coalesce(q.question_text,''),coalesce(q.options_text,''),coalesce(q.correct_answer,''),coalesce(q.explanation,''),coalesce(q.image_url,''),coalesce(q.is_active::text,''),coalesce(q.question_text_ru,''),coalesce(q.question_text_uz,''),coalesce(q.question_text_en,''),coalesce(q.options_text_ru,''),coalesce(q.options_text_uz,''),coalesce(q.options_text_en,''),coalesce(q.explanation_ru,''),coalesce(q.explanation_uz,''),coalesce(q.explanation_en,''),coalesce(q.book_ref,''),coalesce(q.time_limit_sec::text,''),coalesce(q.quality_flag,''),coalesce(q.quality_status,'')))<>m.question_snapshot_md5);
if v_bad<>0 then raise exception 'P1 AW13 circular/trig payload failures=%',v_bad; end if;
select count(*) into v_bad from (select m.id from private.exam_prep_question_content_meta m join public.questions q on q.id=m.question_id left join private.exam_prep_diagnostic_rules r on r.content_meta_id=m.id and r.status='approved' and r.answer_kind='mcq_option' where m.content_version_id=v_id and m.reserve_role='diagnostic' group by m.id,q.correct_answer having count(r.id)<>3 or count(r.id) filter(where r.answer_match=q.correct_answer)<>0) x;
if v_bad<>0 then raise exception 'P1 AW13 circular/trig diagnostic rules failures=%',v_bad; end if;
if (select count(*) from private.exam_prep_question_content_meta m where m.content_version_id=v_id and m.reserve_role='retest' and not exists(select 1 from private.exam_prep_assessment_items i where i.question_id=m.question_id))<>5 then raise exception 'P1 AW13 circular/trig expected 5 R02 isolated holdouts'; end if;
end $$;

update private.exam_prep_question_content_meta m set copyright_status='pass',qa_scope_status='pass',qa_math_status='pass',qa_language_status='pass',qa_technical_status='pass',diagnostic_rule_status=case when reserve_role='diagnostic' then 'approved' else 'not_applicable' end,lifecycle_state='approved',approved_at=now(),updated_at=now() from private.exam_prep_content_versions cv where cv.id=m.content_version_id and cv.content_version='p1_aw13_16_circular_trig_v1' and cv.status='draft';
update private.exam_prep_content_versions set status='approved',approved_at=now() where content_version='p1_aw13_16_circular_trig_v1' and status='draft';
update private.exam_prep_question_content_meta m set lifecycle_state=case when reserve_role='learning' then 'published' else 'reserve' end,exposure_state=case when reserve_role='learning' then 'released' else 'withheld' end,published_at=case when reserve_role='learning' then now() else null end,updated_at=now() from private.exam_prep_content_versions cv where cv.id=m.content_version_id and cv.content_version='p1_aw13_16_circular_trig_v1' and cv.status='approved';
update private.exam_prep_written_tasks w set lifecycle_state='published' from private.exam_prep_content_versions cv where cv.id=w.content_version_id and cv.content_version='p1_aw13_16_circular_trig_v1' and cv.status='approved' and w.lifecycle_state='approved';
update private.exam_prep_assessments a set status='published',approved_at=coalesce(a.approved_at,now()) from private.exam_prep_content_versions cv where cv.id=a.content_version_id and cv.content_version='p1_aw13_16_circular_trig_v1' and cv.status='approved' and a.status='approved';
update private.exam_prep_content_versions set status='published',published_at=now() where content_version='p1_aw13_16_circular_trig_v1' and status='approved';

-- Final acceptance: 5/8 P1 AW13-16 ready; global runway remains RED until the full slice is ready.
do $$ declare v_program bigint; v_skill text; v_ready int; v_r jsonb; v_cfg private.exam_prep_feature_config%rowtype; begin
select id into v_program from private.exam_prep_program_versions where program_key='math_as_p1_p5' and version_key='p1_p5_canonical_v1_0';
foreach v_skill in array array['P1-CIR-03','P1-TRI-02','P1-TRI-03','P1-TRI-04','P1-TRI-05'] loop if not private.exam_prep_skill_content_ready_v1(v_program,'P1',v_skill) then raise exception 'P1 AW13 circular/trig final not ready=%',v_skill; end if; end loop;
select count(*) into v_ready from private.exam_prep_content_runway_release_skills rs join private.exam_prep_content_runway_releases r on r.id=rs.release_id where r.release_key='aw13_16_core_coverage_iii' and r.component_code='P1' and rs.required_for_release and private.exam_prep_skill_content_ready_v1(v_program,'P1',rs.skill_code);
if v_ready<>5 then raise exception 'P1 AW13 circular/trig expected ready=5 got=%',v_ready; end if;
v_r:=public.get_exam_prep_content_runway_v1(13::smallint); if coalesce((v_r->>'hard_floor_green')::boolean,false) then raise exception 'P1 AW13 partial pack must leave global runway RED'; end if;
select * into v_cfg from private.exam_prep_feature_config where id=1; if v_cfg.rollout_state<>'off' or v_cfg.core_enabled or v_cfg.ai_enabled or v_cfg.mentor_enabled or not v_cfg.kill_switch then raise exception 'P1 AW13 circular/trig feature escaped fail-closed'; end if;
if exists(select 1 from private.exam_prep_feature_entitlements where entitlement_status='active') then raise exception 'P1 AW13 circular/trig entitlement residue'; end if;
if exists(select 1 from public.questions where book_ref like 'ExamPrep:P1:p1_aw13_16_circular_trig_v1:%' and is_active) then raise exception 'P1 AW13 circular/trig legacy activation'; end if;
end $$;

commit;
